 useEffect(()=>{if(!storeId)return;void recordInstallation(session,storeId);const timer=setInterval(()=>void recordInstallation(session,storeId),300000);return()=>clearInterval(timer);},[session,storeId]);
 const store=stores.find(s=>s.id===storeId),owner=store?.role==='owner';
 const refresh=useCallback(async()=>{if(!storeId)return;const index=++requestIndex.current;try{const result=await snapshot(session,storeId);if(index!==requestIndex.current)return;setData(result.data);setCached(result.cached);setError('');setQueue(await pending(session,storeId));setReceipts(await localReceipts(session,storeId));}catch(e){if(index===requestIndex.current){setError((e as Error).message);if(e instanceof ApiError&&(e.status===401||e.status===403)){setData(null);setCart([]);setModal(null);setQueue(await pending(session,storeId));}}}finally{setLoading(false);}},[session,storeId]);
 useEffect(()=>{let active=true;api<{stores:Store[]}>('/stores',session).then(r=>{if(!active)return;setStores(r.stores);if(!r.stores.length)setLoading(false);localStorage.setItem(`adfirm-stores-${session.user.id}`,JSON.stringify(r.stores));setStoreId(current=>r.stores.some(s=>s.id===current)?current:r.stores[0]?.id||'');}).catch(e=>{if(!active)return;const saved=localStorage.getItem(`adfirm-stores-${session.user.id}`);if(saved){const list=JSON.parse(saved) as Store[];setStores(list);setStoreId(current=>current||list[0]?.id||'');}else{setError(e.message);setLoading(false);}});return()=>{active=false;};},[session]);
 useEffect(()=>{setData(null);setLoading(true);setCart([]);setReceipt(null);setSearch('');setCategory('All');if(storeId){localStorage.setItem(`adfirm-store-${session.user.id}`,storeId);void refresh();}else setLoading(false);},[storeId,refresh,session.user.id]);
 useEffect(()=>{const sync=async()=>{await flush(session);await refresh();};const visible=()=>{if(document.visibilityState==='visible')void sync();};const timer=setInterval(()=>void sync(),30000);void sync();window.addEventListener('online',sync);window.addEventListener('focus',sync);document.addEventListener('visibilitychange',visible);return()=>{clearInterval(timer);window.removeEventListener('online',sync);window.removeEventListener('focus',sync);document.removeEventListener('visibilitychange',visible);};},[refresh,session]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t);}},[toast]);
