 function scanned(code:string){const value=normalizeBarcode(code),match=products.find(p=>normalizeBarcode(p.barcode||'')===value);setModal(null);if(page==='products'){setSearch(match?.barcode||value);if(!match)setToast('No match. Add a product.');}else if(match){add(match);setPage('sell');}else{setSearch(value);setPage('products');setToast('No match. Add a product.');}}
