 const nav=<>{(Object.keys(icons) as Page[]).map(key=>{const Icon=icons[key];return <button key={key} className={page===key?'nav-item active':'nav-item'} onClick={()=>navigate(key)} aria-current={page===key?'page':undefined}><Icon size={20}/><span>{navLabels[key]}</span>{key==='sell'&&<span className="nav-key" aria-hidden="true">S</span>}</button>;})}</>;
