function Admin({session,logout}:{session:Session;logout:()=>void}){
 const [page,setPage]=useState('overview'),[data,setData]=useState<AdminOverview|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[modal,setModal]=useState<string|null>(null),[notice,setNotice]=useState(''),[agreed,setAgreed]=useState(false);
 const refresh=useCallback(async()=>{try{setData(await api<AdminOverview>('/admin/overview',session));setError('');}catch(e){setError((e as Error).message);}},[session]);useEffect(()=>{void refresh();},[refresh]);
 async function run(task:()=>Promise<void>){setBusy(true);setError('');try{await task();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 const items=[{key:'overview',label:'Overview',icon:House},{key:'stores',label:'Stores',icon:StoreIcon},{key:'billing',label:'Billing',icon:CreditCard},{key:'hardware',label:'Printers',icon:Printer},{key:'devices',label:'Devices',icon:Cloud},{key:'accounts',label:'Accounts',icon:Users},{key:'activity',label:'Activity',icon:ReceiptText},{key:'system',label:'System',icon:Activity}];
 useEffect(()=>{const onError=(e:Event)=>setError((e as CustomEvent<string>).detail);document.addEventListener('adfirm-export-error',onError);return()=>document.removeEventListener('adfirm-export-error',onError);},[]);
 const billing=data?.billing;
 async function updateBilling(mode:Billing['mode']){await run(async()=>{const effectiveAt=mode==='notice'?new Date(Date.now()+30*86400000+120000).toISOString():null;const r=await api<{billing:Billing}>('/admin/billing',session,{method:'PUT',body:JSON.stringify({mode,priceMinor:4900,noticeDays:30,graceDays:7,effectiveAt})});setData(current=>current?{...current,billing:r.billing}:current);setModal(null);setNotice(mode==='free'?'Free mode enabled':'Notice scheduled. No automatic charges.');});}
 return <div className="app-shell admin-shell"><aside className="sidebar"><Logo admin/><div className="workspace-label">SUPER ADMIN</div><nav>{items.map(i=><button key={i.key} className={page===i.key?'nav-item active':'nav-item'} onClick={()=>setPage(i.key)}><i.icon size={19}/>{i.label}</button>)}</nav><div className="sidebar-bottom"><div className="admin-access"><ShieldCheck size={19}/><span>Platform owner<small>Restricted access</small></span></div><button className="profile" onClick={logout}><span className="avatar">AD</span><span><b>{session.user.name}</b><small>Sign out</small></span><LogOut size={16}/></button></div></aside><div className="workspace"><header className="topbar"><div className="mobile-logo"><Logo admin/></div><div className="admin-breadcrumb">Platform <ChevronRight size={13}/> <b>{items.find(i=>i.key===page)?.label}</b></div><div className="topbar-right">{session.demo&&<span className="demo-tag">Demo workspace</span>}<span className="badge"><ShieldCheck size={12}/> Super admin</span></div></header><div className="admin-mobile-tabs">{items.map(i=><button key={i.key} className={page===i.key?'selected':''} onClick={()=>setPage(i.key)}><i.icon size={16}/>{i.label}</button>)}</div><main className="main-content">{error&&<div className="alert error" role="alert">{error}</div>}{notice&&<div className="alert success" role="status">{notice}<button className="icon-button" onClick={()=>setNotice('')} aria-label="Dismiss"><X size={15}/></button></div>}{!data?<div className="loading"><RefreshCw className="spin"/> Loading platform…</div>:<>
 <div className="page-heading"><div><span className="eyebrow">ADFIRM PLATFORM</span><h1>{page==='overview'?'Overview':page==='hardware'?'Printers':page[0].toUpperCase()+page.slice(1)}<span className="heading-dot">.</span></h1><p>{page==='overview'?todayLabel():page==='stores'?'Businesses and branches.':page==='billing'?'Free launch. Paid plan ready.':page==='hardware'?'Hardware inquiries.':'Service status.'}</p></div>{(page==='overview'||page==='stores')&&<Button onClick={()=>{setError('');setModal('business');}}><Plus size={17}/> Add business</Button>}</div>
 {page==='overview'&&<><AdminHub key={data.stores.length} session={session}/><div className="admin-stats"><div className="profit-card"><div className="stat-top"><span>Stores</span><StoreIcon size={21}/></div><strong>{data.stores.length}</strong><small>{data.businessCount} businesses</small></div><div className="stat-card"><div className="stat-top"><span>Billing mode</span><CreditCard size={20}/></div><strong className="word-stat">{billing?.mode==='free'?'Free':'Notice'}</strong><small>₱49 / store / month when activated</small></div><div className="stat-card"><div className="stat-top"><span>Printer inquiries</span><Printer size={20}/></div><strong>{data.hardwareOrders.length}</strong><small>Owner requests</small></div></div><section className="panel"><div className="panel-heading"><div><h2>Stores</h2><p>Connected businesses</p></div><button className="text-button" onClick={()=>setPage('stores')}>View all <ArrowRight size={14}/></button></div><StoreTable stores={data.stores}/></section><div className="admin-bottom-grid"><section className="panel"><div className="panel-heading"><h2>Activity log</h2><Activity size={17}/></div>{data.audit.slice(0,4).map((a,i)=><div className="activity-row" key={i}><span className="tiny-dot"/><span>{a.action.replaceAll('.',' · ')}</span><small>{time(a.createdAt)}</small></div>)}{!data.audit.length&&<p className="fineprint">Platform activity appears here.</p>}</section><section className="panel billing-promo"><CreditCard size={25}/><h2>Micro plan</h2><p>₱49 per store, per month.</p><Button secondary onClick={()=>setPage('billing')}>Manage billing <ArrowRight size={16}/></Button></section></div></>}
 {page==='stores'&&<AdminHub key={data.stores.length} session={session} mode="stores"/>}
 {page==='devices'&&<AdminHub session={session} mode="devices"/>}
 {page==='accounts'&&<AdminHub session={session} mode="accounts"/>}
 {page==='activity'&&<AdminHub session={session} mode="activity"/>}
 {page==='billing'&&<div className="billing-layout"><section className="panel subscription-card"><div className="panel-heading"><h2>Micro plan</h2><span className="badge">{billing?.mode==='free'?'Free launch':'Notice period'}</span></div><div className="plan-price">₱49<span>/ store / month</span></div><p>3 subscribed stores = ₱147 / month</p><div className="finance-row"><span>Notice period</span><b>30 days</b></div><div className="finance-row"><span>Grace period</span><b>7 days</b></div><div className="finance-row"><span>Automatic charging</span><b>Not connected</b></div>{billing?.effectiveAt&&<div className="finance-row"><span>Notice ends</span><b>{new Date(billing.effectiveAt).toLocaleDateString('en-PH',{timeZone:'Asia/Manila'})}</b></div>}<div className="finance-note">Subscription collection and access enforcement are not enabled in this build.</div>{billing?.mode==='free'?<Button className="full-width" onClick={()=>{setAgreed(false);setError('');setModal('billing');}}>Schedule paid notice <ArrowRight size={16}/></Button>:<Button className="full-width" onClick={()=>void updateBilling('free')} disabled={busy}>Return to free mode</Button>}</section><section className="panel billing-rules"><h2>Owner-first billing</h2><div><span className="row-icon"><CheckCheck size={19}/></span><span><b>Clear notice</b><small>30 days before paid enrollment</small></span></div><div><span className="row-icon"><ShieldCheck size={19}/></span><span><b>Explicit consent</b><small>No automatic charges</small></span></div><div><span className="row-icon"><Cloud size={19}/></span><span><b>Keep records accessible</b><small>Sync and export remain available</small></span></div></section></div>}
 {page==='hardware'&&<section className="panel"><div className="panel-heading"><h2>Printer inquiries</h2><span className="count-badge">{data.hardwareOrders.length}</span></div>{data.hardwareOrders.map(order=><div className="list-row" key={order.id}><span className="row-icon"><Printer size={20}/></span><div><b>{order.businessName}</b><small>{order.storeName} · {order.productName}</small></div><label className="field inquiry-status">Status<select aria-label={`Inquiry status ${order.id}`} value={order.status} disabled={busy} onChange={e=>{const status=e.target.value;void run(async()=>{await api(`/admin/hardware-orders/${order.id}`,session,{method:'PUT',body:JSON.stringify({status})});await refresh();setNotice('Inquiry updated');});}}>{['inquiry','contacted','quoted','closed'].map(s=><option key={s}>{s}</option>)}</select></label></div>)}{!data.hardwareOrders.length&&<Empty icon={Printer} title="No inquiries yet" detail="Owner requests appear here."/>}</section>}
 {page==='system'&&<><section className="panel system-panel"><div className="finance-row"><span>API</span><span className="badge">Connected</span></div><div className="finance-row"><span>Image storage</span><b>{data.storage==='r2'?'Cloudflare R2':'Local development'}</b></div><div className="finance-row"><span>Photo recognition</span><b>{data.recognitionEnabled?'Configured':'Not configured'}</b></div><div className="finance-row"><span>Image format</span><b>WebP · Up to 200 KB</b></div><div className="finance-row"><span>Maximum image edge</span><b>1,200 px</b></div><div className="finance-row"><span>Billing collection</span><b>Not connected</b></div><div className="finance-row"><span>Environment</span><b>{data.demo?'Demo':'Configured server'}</b></div><div className="finance-note">Staging environment</div></section><section className="panel account-panel"><h2>Account security</h2><Account session={session}/></section><IntegrityPanel session={session}/></>}
 </>}</main></div>{modal&&<Modal title={modal==='billing'?'Review paid notice':'Add business'} onClose={()=>{if(!busy)setModal(null);}}>{error&&<div className="alert error" role="alert">{error}</div>}{modal==='billing'?<><div className="payment-amount"><span>Micro plan</span><strong>₱49</strong><small>Per store / month</small></div><p className="fineprint">Starts a 30-day notice. No store will be charged or locked out. Payment-provider integration is a separate release.</p><label className="checkbox-row"><input type="checkbox" checked={agreed} onChange={e=>setAgreed(e.target.checked)}/><span>Confirm notice and pricing</span></label><Button disabled={!agreed||busy} className="full-width" onClick={()=>void updateBilling('notice')}>Schedule notice</Button></>:<form onSubmit={e=>{e.preventDefault();const form=new FormData(e.currentTarget);void run(async()=>{await api('/admin/businesses',session,{method:'POST',body:JSON.stringify(Object.fromEntries(form.entries()))});setModal(null);setNotice('Business and owner account created');await refresh();});}}><Field label="Business name" name="businessName"/><div className="form-grid"><Field label="Store name" name="storeName"/><Field label="Location" name="location" required={false}/></div><Field label="Owner name" name="ownerName"/><Field label="Owner email" name="email" type="email"/><Field label="Initial password" name="password" type="password" placeholder="At least 12 characters"/><Button type="submit" disabled={busy} className="full-width">{busy?'Creating…':'Create business'}</Button></form>}</Modal>}</div>;
}
function StoreTable({stores}:{stores:AdminOverview['stores']}){return <div className="responsive-table"><table><thead><tr><th>Business</th><th>Store</th><th>Location</th><th>Sales recorded</th></tr></thead><tbody>{stores.map(s=><tr key={s.id}><td><div className="business-cell"><span className="row-icon"><StoreIcon size={19}/></span><b>{s.businessName}</b></div></td><td>{s.name}</td><td>{s.location||'—'}</td><td>{s.saleCount}</td></tr>)}</tbody></table>{!stores.length&&<Empty icon={StoreIcon} title="No stores yet"/>}</div>;}
